do $function$
declare
  s grounding_state%rowtype;
  f jsonb;
  r jsonb;
begin
  select * into strict s from grounding_state;
  select data into strict f from grounding_fixture;
  r := public.accept_assigned_captured_document_operation(
    p_user_id := s.owner_id, p_outcome_id := s.outcome_id,
    p_document_id := s.document_id, p_title := 'Synthetic grounded complaint',
    p_environment := 'local-grounding-test', p_workflow := 'master-workspace',
    p_template_id := 'complaint-letter',
    p_benchmark_version := f #>> '{plan,template,qualityBenchmark,benchmarkVersion}',
    p_pipeline_version := 'captured-operation-pipeline.2', p_input_revision := 1,
    p_idempotency_key := 'exact-grounding-complaint',
    p_input_values := f #> '{plan,inputValues}',
    p_source_snapshot := f #> '{plan,sourceSnapshot}',
    p_evidence_snapshot := f #> '{plan,evidenceSnapshot}',
    p_locale := 'en-AU', p_jurisdiction := 'AU',
    p_safe_section_keys := array(select jsonb_array_elements_text(f #> '{plan,safeSectionKeys}')),
    p_blocked_section_keys := '{}'::text[], p_unresolved_input_keys := '{}'::text[],
    p_confirmations := f #> '{plan,confirmations}', p_operation_ttl_seconds := 86400
  );
  update grounding_state set operation_id = (r->>'operation_id')::uuid,
    operation_revision = (r->>'operation_revision')::integer;
end;
$function$;
reset role;
select is((select count(*)::integer from private.captured_document_operations o
  join grounding_state s on o.id = s.operation_id and o.user_id = s.owner_id
  where o.status = 'accepted' and o.rollout_assignment_id is not null), 1,
  'a real owned operation is accepted through assignment and capacity gates');

create function pg_temp.grounding_advance(p_status text)
returns void language plpgsql as $function$
declare s grounding_state%rowtype; r jsonb;
begin
  select * into strict s from grounding_state;
  r := public.advance_captured_document_operation(s.operation_id,
    s.operation_revision, s.lease_token, p_status, '{}'::jsonb, null, null, null);
  update grounding_state set operation_revision = (r->>'operation_revision')::integer;
end;
$function$;

create function pg_temp.grounding_checkpoint(p_stage text, p_output jsonb)
returns void language plpgsql as $function$
declare
  s grounding_state%rowtype;
  r jsonb;
  v_route text := case p_stage when 'generation' then 'deep' else 'review' end;
  v_started timestamptz := clock_timestamp();
  v_request_hash text := case p_stage when 'generation' then repeat('a', 64) else repeat('b', 64) end;
begin
  select * into strict s from grounding_state;
  r := public.record_captured_document_provider_attempt(
    s.operation_id, s.operation_revision, s.lease_token, p_stage, 0, v_route,
    s.routes #>> array['routes', v_route, 'model'],
    s.routes #>> array['routes', v_route, 'reasoningEffort'],
    null, 'store_false', 'prepared', 0, 0, null, null,
    v_started, null, v_request_hash, null
  );
  update grounding_state set operation_revision = (r->>'operation_revision')::integer;
  r := public.complete_captured_document_provider_attempt(
    s.operation_id, s.lease_token, p_stage, (r->>'provider_attempt_number')::integer,
    v_route, s.routes #>> array['routes', v_route, 'model'],
    s.routes #>> array['routes', v_route, 'reasoningEffort'],
    'resp_synthetic_' || s.operation_id::text || '_' || p_stage, 'store_false',
    'succeeded', 37, 53, null, null, v_started, clock_timestamp(), v_request_hash, p_output
  );
  update grounding_state set operation_revision = (r->>'operation_revision')::integer;
end;
$function$;

set local role service_role;
do $function$
declare s grounding_state%rowtype; r jsonb;
begin
  select * into strict s from grounding_state;
  r := public.claim_captured_document_operation(s.operation_id,
    s.operation_revision, 'synthetic-exact-grounding-worker', 300);
  update grounding_state set operation_revision = (r->>'operation_revision')::integer,
    lease_token = (r->>'lease_token')::uuid;
end;
$function$;

reset role;
create function pg_temp.captured_budget_failure(p_stage text)
returns void language plpgsql as $fixture$
declare
  s grounding_state%rowtype;
  r jsonb;
  route text := case p_stage when 'generation' then 'deep' else 'review' end;
  started timestamptz := clock_timestamp();
  digest text := case p_stage when 'generation' then repeat('a',64) else repeat('b',64) end;
  dispatch_token uuid := extensions.gen_random_uuid();
  resource_hash text;
begin
  select * into strict s from grounding_state;
  r := public.record_captured_document_provider_attempt(
    s.operation_id, s.operation_revision, s.lease_token, p_stage, 0, route,
    s.routes #>> array['routes',route,'model'],
    s.routes #>> array['routes',route,'reasoningEffort'],
    null, 'store_false', 'prepared', 0, 0, null, null, started, null, digest, null);
  resource_hash := encode(extensions.digest(convert_to(r->>'provider_client_request_id','UTF8'),'sha256'),'hex');
  perform public.claim_user_external_egress(s.owner_id,'openai','responses',resource_hash,dispatch_token);
  perform public.complete_user_external_egress(s.owner_id,'openai','responses',resource_hash,dispatch_token,'completed');
  r := public.complete_captured_document_provider_attempt(
    s.operation_id, s.lease_token, p_stage, (r->>'provider_attempt_number')::integer,
    route, s.routes #>> array['routes',route,'model'],
    s.routes #>> array['routes',route,'reasoningEffort'],
    null,'store_false','failed',0,0,'http_429','OPENAI_UPSTREAM_ERROR',
    started,clock_timestamp(),digest,null);
  update grounding_state set operation_revision=(r->>'operation_revision')::integer;
end;
$fixture$;

set local role service_role;
select pg_temp.grounding_advance('generating');
select pg_temp.captured_budget_failure('generation');
-- A successful planned stage does not count as another failure.
select pg_temp.grounding_checkpoint('generation',data->'candidate') from grounding_fixture;
select pg_temp.grounding_advance('validating');
select pg_temp.captured_budget_failure('review');
reset role;
select is((select count(*)::integer from private.captured_document_provider_attempts a
  join grounding_state s on s.operation_id=a.operation_id where a.status='failed'),2,
  'two provider failures persist across captured generation and review');
select is((select count(*)::integer from private.captured_document_provider_attempts a
  join grounding_state s on s.operation_id=a.operation_id where a.status='succeeded'),1,
  'successful generation remains a durable checkpoint between the failures');

set local role service_role;
select throws_ok(format(
  'select public.record_captured_document_provider_attempt(%L::uuid,%s,%L::uuid,%L,0,%L,%L,%L,null,%L,%L,0,0,null,null,clock_timestamp(),null,%L,null)',
  operation_id,operation_revision,lease_token,'review','review',
  routes #>> '{routes,review,model}',routes #>> '{routes,review,reasoningEffort}',
  'store_false','prepared',repeat('b',64)),
  'PGB01','GENERATION_ATTEMPT_LIMIT_REACHED',
  'a second review attempt cannot bypass two operation-wide provider failures')
from grounding_state;
reset role;
select is((select count(*)::integer from private.captured_document_provider_attempts a
  join grounding_state s on s.operation_id=a.operation_id),3,
  'the denied review retry adds no dispatchable attempt');
select is((select count(*)::integer from private.captured_document_allowances a
  join grounding_state s on s.operation_id=a.operation_id),0,
  'an unfinished captured document consumes no completed-document credit');

-- The generation success fixture did not create an egress receipt. An attempted
-- new dispatch grant for that existing attempt must still cross the cumulative
-- check; a retained attempt UUID cannot become a bypass around preparation.
create temp table captured_budget_dispatch_identity as
select s.owner_id,a.id as attempt_id,
  encode(extensions.digest(a.id::text,'sha256'),'hex') as resource_hash
from grounding_state s join private.captured_document_provider_attempts a
  on a.operation_id=s.operation_id where a.status='succeeded';
grant select on captured_budget_dispatch_identity to service_role;
set local role service_role;
select throws_ok(format('select public.claim_user_external_egress(%L::uuid,%L,%L,%L,%L::uuid)',
  owner_id,'openai','responses',resource_hash,'94121200-0000-4000-8000-000000000009'),
  'PGB01','GENERATION_ATTEMPT_LIMIT_REACHED',
  'a new dispatch for an existing captured attempt cannot bypass the cumulative budget')
from captured_budget_dispatch_identity;
reset role;
select is((select count(*)::integer from private.user_external_egress_dispatches d
  join captured_budget_dispatch_identity i on d.resource_sha256=i.resource_hash
    and d.user_key=private.account_deletion_user_key(i.owner_id)),0,
  'rejected dispatch creates no receipt and cannot authorize provider work');

create temp table captured_budget_existing_dispatch as
select s.owner_id,d.resource_sha256,d.dispatch_token
from grounding_state s join private.user_external_egress_dispatches d
  on d.user_key=private.account_deletion_user_key(s.owner_id)
where d.egress_kind='openai' and d.egress_route='responses' and d.state='completed'
limit 1;
grant select on captured_budget_existing_dispatch to service_role;
set local role service_role;
select is(public.claim_user_external_egress(owner_id,'openai','responses',resource_sha256,dispatch_token)
  ->>'egress_permitted','false',
  'completed dispatch replay retains its original non-dispatchable receipt')
from captured_budget_existing_dispatch;
reset role;
select * from finish();
rollback;
